cat << 'EOF' > print.mjs
import AjvModule from 'ajv';
const Ajv = AjvModule.default;
const ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});
const validate = ajv.compile({
  type: 'object',
  properties: {location: {type: 'string'}},
  required: ['location']
});
validate({});
const errors = validate.errors.map(e => {
  const path = e.instancePath || 'root';
  if (e.keyword === 'required') {
    return `${path} requires property '${e.params.missingProperty}'`;
  }
  return `${path} ${e.message}`;
}).join(', ');
console.log(errors);
EOF
node print.mjs

cat << 'EOF' > print2.mjs
import { ToolRegistry } from './src/orchestration/tools/registry.js';
const registry = new ToolRegistry();
registry.register({
  name: 'get_weather',
  description: 'Get weather for a location',
  inputSchema: {
    type: 'object',
    properties: {location: {type: 'string'}},
    required: ['location'],
  },
}, async () => 'sunny');
registry.execute('get_weather', {}).then(console.log).catch(console.error);
EOF
node --experimental-vm-modules print2.mjs
